_validate_upgrade:
	# upgrade cost = delta of capacity cost proxy (tier.cost_per_tile × current span)
	var cost: int = Economy.draw_cost(p.span_tiles, tier.cost_per_tile)
	if economy != null and not economy.can_afford(cost):
		return EditResult.rejected(&"over_budget")
_apply_upgrade:
	var new_cost: int = Economy.draw_cost(p.span_tiles, new_tier.cost_per_tile)
	var old_cost: int = Economy.draw_cost(p.span_tiles, old_tier.cost_per_tile)
	economy.spend(maxi(0, new_cost - old_cost))

func evaluate(tick: int, _topology: TopologySnapshot, _flow: PacketFlow,
		  era_id: int, director: ScriptedDirector) -> CrisisReport:
	var report := CrisisReport.new()
	report.tick = tick
	if director != null:
		report.forecast = director.forecast_for_era(era_id, tick)
	# E4.1-E4.3 (S4): compute strain metrics, raise WarningSigns, fire fair crises
	# each carrying a root_cause + preventive_redesign (§10.1.3, AC-E13).
	return report
